// FUNCTIONS //

/**
* Tests whether two Complex64Arrays have equal contents.
*
* @private
* @param {Object} t - tape test object
* @param {Complex64Array} actual - actual value
* @param {Array} expected - expected interleaved values
* @param {string} msg - message
*/
function isEqualC64( t, actual, expected, msg ) {
	var view;
	var i;

	view = reinterpret( actual, 0 );
	for ( i = 0; i < expected.length; i++ ) {
		t.ok( Math.abs( expected[ i ] - view[ i ] ) < 1.0e-4, msg + ' [' + i + ']: expected ' + expected[ i ] + '. actual: ' + view[ i ] );
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ctrsv, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 9', function test( t ) {
	t.strictEqual( ctrsv.length, 9, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var data;
	var i;

	data = rutu;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			ctrsv( value, data.uplo, data.trans, data.diag, data.N, new Complex64Array( data.A ), data.LDA, new Complex64Array( data.x ), data.strideX );
		};
	}
});

