tape( 'the function solves `A*x = b` or `A^T*x = b` (row-major, lower, no-transpose, non-unit)', function test( t ) {
	var data;
	var out;
	var a;
	var x;

	data = rlntnu;

	a = new Complex64Array( data.A );
	x = new Complex64Array( data.x );

	out = ctrsv( data.order, data.uplo, data.trans, data.diag, data.N, a, data.LDA, x, data.strideX );
	t.strictEqual( out, x, 'returns expected value' );
	isEqualC64( t, out, data.x_out, 'returns expected value' );

	t.end();
});

